const jwt = require('jsonwebtoken');
const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function run() {
  const projectId = process.env.PARAGON_PROJECT_ID;
  const signingKey = process.env.PARAGON_SIGNING_KEY.replace(/\\n/g, '\n');
  const userId = 'test-user';

  if (!projectId || !signingKey) {
    console.error('Missing PARAGON_PROJECT_ID or PARAGON_SIGNING_KEY');
    process.exit(1);
  }

  // 1. Generate Paragon User Token (JWT)
  const token = jwt.sign(
    {
      sub: userId,
      iat: Math.floor(Date.now() / 1000),
    },
    signingKey,
    {
      algorithm: 'RS256',
      expiresIn: '1h',
    }
  );

  // 2. Make request to Paragon Proxy API for PostgreSQL
  const url = `https://proxy.useparagon.com/projects/${projectId}/sdk/proxy/postgresql`;
  const query = "INSERT INTO users (name, email) VALUES ('Alice', 'alice@example.com') RETURNING *;";

  try {
    const response = await axios.post(
      url,
      { query },
      {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      }
    );

    console.log('Success:', response.data);

    // 3. Write result to /home/user/project/result.json
    fs.writeFileSync(
      '/home/user/project/result.json',
      JSON.stringify(response.data, null, 2)
    );
  } catch (error) {
    console.error('Error:', error.response ? error.response.data : error.message);
    const errorData = error.response ? error.response.data : { error: error.message };
    fs.writeFileSync(
      '/home/user/project/result.json',
      JSON.stringify(errorData, null, 2)
    );
    process.exit(1);
  }
}

